diff --git a/src/async-pool.mjs b/src/async-pool.mjs
index ec4e7bc..4df682c 100644
--- a/src/async-pool.mjs
+++ b/src/async-pool.mjs
@@ -7,7 +7,89 @@
 //   （即 results[i] 对应 tasks[i] 的返回值，而不是按完成先后排列）。
 // - 任意时刻并发数不得超过 limit。
 //
-// 详细契约见 prompt。下面是一个未实现的占位实现。
-export async function runPool(tasks, limit) {
-  throw new Error("not implemented");
+// 详细契约见 prompt。
+export function runPool(tasks, limit) {
+  if (tasks.length === 0) {
+    return Promise.resolve([]);
+  }
+
+  if (!(limit > 0)) {
+    return Promise.reject(new RangeError("runPool limit must be greater than 0"));
+  }
+
+  const maxConcurrent = Math.min(Math.max(1, Math.trunc(limit)), tasks.length);
+  const results = new Array(tasks.length);
+
+  return new Promise((resolve, reject) => {
+    let nextIndex = 0;
+    let active = 0;
+    let stopped = false;
+    let finished = false;
+    let firstErrorIndex = Infinity;
+    let firstError;
+
+    const rememberError = (index, error) => {
+      if (index < firstErrorIndex) {
+        firstErrorIndex = index;
+        firstError = error;
+      }
+    };
+
+    const finishIfReady = () => {
+      if (finished) {
+        return;
+      }
+
+      if (stopped) {
+        if (active === 0) {
+          finished = true;
+          reject(firstError);
+        }
+        return;
+      }
+
+      launchAvailable();
+
+      if (nextIndex === tasks.length && active === 0) {
+        finished = true;
+        resolve(results);
+      }
+    };
+
+    const settleSuccess = (index, value) => {
+      results[index] = value;
+      active -= 1;
+      finishIfReady();
+    };
+
+    const settleFailure = (index, error) => {
+      rememberError(index, error);
+      stopped = true;
+      active -= 1;
+      finishIfReady();
+    };
+
+    function launchAvailable() {
+      while (!stopped && active < maxConcurrent && nextIndex < tasks.length) {
+        const index = nextIndex;
+        nextIndex += 1;
+        active += 1;
+
+        let taskResult;
+        try {
+          taskResult = tasks[index]();
+        } catch (error) {
+          settleFailure(index, error);
+          continue;
+        }
+
+        Promise.resolve(taskResult).then(
+          (value) => settleSuccess(index, value),
+          (error) => settleFailure(index, error),
+        );
+      }
+    }
+
+    launchAvailable();
+  });
 }

